SELECT id, user_id, title, content, type, related_id, is_read, create_time, update_time, deleted
FROM t_notification
WHERE deleted = 0

    AND user_id = #{userId}


    AND type = #{type}


    AND is_read = #{isRead}

ORDER BY create_time DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM t_notification
WHERE deleted = 0

    AND user_id = #{userId}


    AND type = #{type}


    AND is_read = #{isRead}
